import{c as t,S as r,j as o,m as a}from"./chunks/framework.C68YPdek.js";const u=JSON.parse('{"title":"Contributing","description":"","frontmatter":{},"headers":[],"relativePath":"developer/contributing.md","filePath":"developer/contributing.md"}'),i={name:"developer/contributing.md"};function s(n,e,h,l,c,p){return r(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="contributing" tabindex="-1">Contributing <a class="header-anchor" href="#contributing" aria-label="Permalink to “Contributing”">​</a></h1><p>How to contribute to Source Academy, in any of its repositories. This is the page that the organisation&#39;s default <a href="https://github.com/source-academy/.github/blob/main/CONTRIBUTING.md" target="_blank" rel="noreferrer"><code>CONTRIBUTING.md</code></a> points to. A repository can have its own <code>CONTRIBUTING.md</code> with more detail (the frontend does, on its application structure and testing); that one comes first where the two differ.</p><h2 id="the-short-version" tabindex="-1">The short version <a class="header-anchor" href="#the-short-version" aria-label="Permalink to “The short version”">​</a></h2><ol><li><strong>Start from an issue.</strong> Look in the issue tracker of the repository for something to work on, or open an issue to describe what you want to change. For anything larger than a small fix, wait for a reply before you start, so that the work does not collide with a plan that you cannot see.</li><li><strong>Fork the repository</strong> and make a branch in your fork. Write access to the repositories is limited to the organisation&#39;s owners, so everybody else contributes from a fork. GitHub&#39;s <a href="https://docs.github.com/en/get-started/quickstart/fork-a-repo" target="_blank" rel="noreferrer">fork a repo</a> page explains how.</li><li><strong>Make the change</strong> and run the checks of the repository (format, lint, test, build: the scripts of <code>package.json</code>, or the commands in the README) before you push.</li><li><strong>Open a pull request</strong> that says what changed and why, and which issue it closes. The repository&#39;s pull-request template (or the organisation&#39;s default) shows what to include.</li><li><strong>Answer the review.</strong> An owner reviews the pull request. Change what the review asks for, or explain why not, and the pull request is merged when the checks pass and the review approves.</li></ol><h2 id="what-to-expect-from-a-pull-request" tabindex="-1">What to expect from a pull request <a class="header-anchor" href="#what-to-expect-from-a-pull-request" aria-label="Permalink to “What to expect from a pull request”">​</a></h2><ul><li><strong>A pull request is required</strong> to change the default branch of a repository, and force pushes and deletion of the branch are blocked. The repositories that only hold built output (the deployment repositories, such as <code>docs.sourceacademy.org</code>) are written by workflows instead.</li><li><strong>Most repositories require one approving review</strong>, and some require passing checks (for example the tests, the linter or the build). The checks that a repository requires are listed in its branch protection or ruleset, and you see them at the bottom of the pull request.</li><li><strong>Merged branches are deleted</strong> automatically.</li><li><strong>Dependencies</strong> are updated by Dependabot pull requests. Reviewing one is a good first contribution: read what changed, and check that the checks pass.</li></ul><h2 id="conventions-that-apply-everywhere" tabindex="-1">Conventions that apply everywhere <a class="header-anchor" href="#conventions-that-apply-everywhere" aria-label="Permalink to “Conventions that apply everywhere”">​</a></h2><ul><li><strong>Node.js:</strong> every repository that uses it uses one version, described on the <a href="./node-version">Node.js version</a> page.</li><li><strong>Comments:</strong> the playbook is on the <a href="./comment-cleanup">Cleaning up comments</a> page. A pull request that only changes comments follows it.</li><li><strong>One change per pull request.</strong> A small pull request is reviewed sooner than a large one, and is easier to take back.</li></ul><h2 id="reporting-a-security-problem" tabindex="-1">Reporting a security problem <a class="header-anchor" href="#reporting-a-security-problem" aria-label="Permalink to “Reporting a security problem”">​</a></h2><p>Do not open a public issue. Use GitHub&#39;s private vulnerability reporting, as described in the <a href="https://github.com/source-academy/.github/blob/main/SECURITY.md" target="_blank" rel="noreferrer">security policy</a>.</p><h2 id="behaviour" tabindex="-1">Behaviour <a class="header-anchor" href="#behaviour" aria-label="Permalink to “Behaviour”">​</a></h2><p>Everyone who takes part in the project is expected to follow the <a href="https://github.com/source-academy/.github/blob/main/CODE_OF_CONDUCT.md" target="_blank" rel="noreferrer">code of conduct</a>.</p><h2 id="for-maintainers-a-new-repository" tabindex="-1">For maintainers: a new repository <a class="header-anchor" href="#for-maintainers-a-new-repository" aria-label="Permalink to “For maintainers: a new repository”">​</a></h2><p>The organisation&#39;s security settings (Dependabot, CodeQL, secret scanning with push protection, private vulnerability reporting) apply to a new repository by themselves. The protection of its default branch does not, because the organisation is on a plan without organisation-wide rulesets. The checklist is in the <a href="https://github.com/source-academy/.github#checklist-for-a-new-repository" target="_blank" rel="noreferrer">README of the <code>.github</code> repository</a>: in short, run <code>scripts/apply-baseline.sh --apply &lt;repository&gt;</code>.</p>',14)])])}const g=t(i,[["render",s]]);export{u as __pageData,g as default};
